-- Get the current slash direction for the current OS platform
local osSep = package.config:sub(1,1)

-- Get the current OS platform
local platform = (FuPLATFORM_WINDOWS and 'Windows') or (FuPLATFORM_MAC and 'Mac') or (FuPLATFORM_LINUX and 'Linux')

-- The Substance "PBR Metal Rough" texture map names
local channels = {
	'BaseColor',
	'Roughness',
	'Metallic',
	'Height',
	'Emissive',
	'Normal',
}

-- Lua table of the image filenames
local imageFilenames = {}
local imageChannels = {}

-- Find out if we are running in Fusion 9/16+ or Resolve 15/16+
local ver = app:GetVersion()
appVersion = ver[1] + ver[2]/10 + ver[3]/100
appName = ver.App or (ver[1] < 15 and 'Fusion' or 'Resolve')

-- Display the extra debugging verbosity detail in the console log
-- printStatus = true
printStatus = false

-- Set a fusion specific preference value
-- Example: SetPreferenceData('Substance.PBRImport.usePBRMaterial', false, printStatus)
function SetPreferenceData(pref, value, status)
	comp:SetData(pref, value)
	-- app:SetData(pref, value)

	-- List the preference value
	if status == 1 or status == true then
		if value ~= nil then
			print('[Setting ' .. pref .. ' Preference Data] ' .. tostring(newPreference))
		else
			print('[Setting ' .. pref .. ' Preference Data] ' .. 'nil')
		end

		print('[Reading Stored' .. pref .. ' Preference Data] ' .. tostring(comp:GetData(pref)))
	end
end

-- Read a fusion specific preference value. If nothing exists set and return a default value
-- Example: GetPreferenceData('Substance.PBRImport.usePBRMaterial', false, printStatus)
function GetPreferenceData(pref, defaultValue, status)
	local newPreference = comp:GetData(pref)
	-- local newPreference = app:GetData(pref)
	if newPreference ~= nil then
		-- List the existing preference value
		if status == 1 or status == true then
			print('[Reading ' .. pref .. ' Preference Data] ' .. tostring(newPreference))
		end
	else
		-- Force a default value into the preference & then list it
		newPreference = defaultValue

		comp:SetData(pref, newPreference)
		-- app:SetData(pref, defaultValue)

		if status == 1 or status == true then
			print('[Creating Fallback '.. pref .. ' Preference Entry] ' .. tostring(newPreference))
		end
	end

	return newPreference
end

-- Get the base filename from a filepath
function GetFilename(mediaDirName)
	local path, basename = string.match(mediaDirName, "^(.+[/\\])(.+)")

	return basename
end

-- Get the base filename with the frame number left intact
function GetBasename(mediaDirName)
	local path, basename,name, extension, barename, sequence = ''
	if mediaDirName then
		path, basename = string.match(mediaDirName, '^(.+[/\\])(.+)')
		if basename then
			name, extension = string.match(basename, '^(.+)(%..+)$')
			if name then
				barename, sequence = string.match(name, '^(.-)(%d+)$')
			end
		end
	end

	return name or ''
end

-- Get the file extension from a filepath
function GetExtension(mediaDirName)
	local extension = ''
	if mediaDirName then
		extension = string.match(mediaDirName, '(%..+)$')
	end

	return extension or ''
end

-- Get the Loader node FormatID from a filepath
function GetFormatID(mediaDirName)
	local extension = ''
	if mediaDirName then
		extension = string.lower(string.match(mediaDirName, '(%..+)$'))
	end

	local formatID = ''

	if extension == '.exr' then
		formatID = 'OpenEXRFormat'
	elseif extension == '.png' then
		formatID = 'PNGFormat'
	elseif extension == '.jpg' then
		formatID = 'JpegFormat'
	elseif extension == '.jp2' then
		formatID = 'Jpeg2000Format'
	elseif extension == '.tif' then
		formatID = 'TiffFormat'
	elseif extension == '.tiff' then
		formatID = 'TiffFormat'
	else
		formatID = 'PNGFormat'
	end

	print('\t[Format ID]', formatID, '[Ext]', extension, '[File]', mediaDirName)

	return formatID
end

-- Split apart a filepath and get the parent dir, the current dir, the filename, filename without the extension, and the file extension.
-- Example: parentDirectory, currentDirectory, currentFile, currentFileNoExt, currentExtension = SplitFilepath('/Volumes/Media/Bridge/Under the Bridge.0000.tif')
function SplitFilepath(dirpath)
	-- Break the elements apart using the matching pattern '(.*/)(.*/)')
	local parentDir, currentDir = string.match(dirpath, '(.*' .. osSep ..')(.*' .. osSep ..')')

	local filename = GetFilename(dirpath)
	local filenameNoExt = GetBasename(dirpath)
	local ext = GetExtension(dirpath)

	return parentDir, currentDir, filename, filenameNoExt, ext
end

-- Reduce double slashes in the filepath down to single slashes
function RemoveDupSlashes(path)
	path = string.gsub(path, [[//]], [[/]])
	path = string.gsub(path, [[\\]], [[\]])
	return path
end

-- Convert mixed Windows/Unix style slashes in a filepath into a consistent slash character for the current OS
function NormalizeSlashes(path)
	if platform == 'Windows' then
		local result = RemoveDupSlashes(string.gsub(path, [[/]], [[\]]))
		return result
	else
		local result = RemoveDupSlashes(string.gsub(path, [[\]], [[/]]))
		return result
	end
end


-- Create the new image nodes for the comp
function AddImageNodes(usePBRMaterial, useEnvMap, useShaderBall, useNote)
	-- Build Nodes Right
	nodeAlignment = 'right'
	-- print('[Node Layout / Build Direction] ' .. nodeAlignment)

	-- Node Positions - read from the Fusion cursor / last node position in the future.
	nodeX = 605
	nodeY = 346

	-- -----------------------------------------
	-- Create the block of loader node elements
	-- -----------------------------------------

	-- Open the Fusion comp tags
	loaderNodes = '{\n'
	loaderNodes = loaderNodes .. '\tTools = ordered() {\n'

	-- Loop through loading each of the images
	-- totalNodes = #imageFilenames - 1
	nodeNumber = 1

	for i, img in pairs(imageFilenames) do
		nodeLoaderName = GetBasename(img)
		imageFormatFusion = GetFormatID(img)
		chan = imageChannels[i]

		-- Add the newest loader node
		-- print('[Adding Loader Node] ' .. tostring(nodeLoaderName) .. ' [Media] ' .. tostring(img))
		loaderNodes = loaderNodes .. CreateLoaderNodes(nodeNumber, nodeLoaderName, img, chan, usePBRMaterial, useEnvMap, useShaderBall, useNote, imageFormatFusion, nodeX, nodeY, nodeAlignment)

		-- Track the current node for the placement in the scene
		nodeNumber = nodeNumber + 1
	end

	-- Close the Fusion comp tags
	loaderNodes = loaderNodes .. '\t}\n}\n\n'

	print('[Creating Loader Nodes]')
	print(loaderNodes)

	local nodeTable = bmd.readstring(loaderNodes)
	-- dump(nodeTable)

	-- Add the nodes to the clipboard
	if nodeTable then
		-- Paste the clipboard into the Fusion Studio comp
		comp:Paste(nodeTable)
		wait(0.1)
	else
		print('[Copy to Clipboard] The Copy to Clipboard task failed due to empty (nil) node data')
	end
end

-- Add an extra loader node to the comp
function CreateLoaderNodes(nodeNumber, loaderName, loaderFilename, nodeChannel, usePBRMaterial, useEnvMap, useShaderBall, useNote, loaderFormat, nodeOriginXPos, nodeOriginYPos, align)
	-- loaderFormat holds a value like 'PNGFormat'

	-- Node spacing per row/column
	nodeXOffset = 110
	nodeYOffset = 33.5

	-- Skip adding a frame extension number
	frameExtensionFusionStartFrame = -1

	-- IBL Environment map
	iblName = 'kas_Simons_Town_Rocks'
	iblFilename = 'Macros:/KickAss ShaderZ/Assets/kas_Simons_Town_Rocks_CapeTown_SouthAfrica_IBL.exr'
	iblFormat = 'OpenEXRFormat'
	iblLoaderText = [[Simon's Town Rocks, Cape Town, South Africa IBL \n\nCreative Commons:\nSimon\'s Town Rocks \n\nBy:\nhttps://hdrihaven.com/ \n\nIs licensed under:\nCC0 (Public Domain)]]

	-- Number of inline nodes in the branch to shift over by
	nodeBranchShift = 0

	-- Add the Loader node by calculating the node index # that is being added
	nodeBranchShift = 0
	loaderXPos = nodeOriginXPos + (nodeXOffset * nodeBranchShift)
	loaderYPos = nodeOriginYPos + (nodeYOffset * nodeNumber)

	-- The Note node goes above the Loader node
	nodeBranchShift = nodeBranchShift
	noteNodeXPos = nodeOriginXPos + (nodeXOffset * nodeBranchShift)
	noteNodeYPos = nodeOriginYPos + (nodeYOffset * (nodeNumber - 7))

	-- The IBL Loader node goes above the Loader node
	nodeBranchShift = nodeBranchShift
	loaderIBLXPos = nodeOriginXPos + (nodeXOffset * nodeBranchShift)
	loaderIBLYPos = nodeOriginYPos + (nodeYOffset * (nodeNumber - 1))

	-- The IBL SphereMap node goes above the Loader node
	if usePBRMaterial == true then
		nodeBranchShift = 1
	else
		nodeBranchShift = 3
	end
	spheremapIBLXPos = nodeOriginXPos + (nodeXOffset * nodeBranchShift)
	spheremapIBLYPos = nodeOriginYPos + (nodeYOffset * (nodeNumber - 1))

	-- Add the CookTorrance Material node by calculating the node index # that is being added
	nodeBranchShift = 2
	materialCookTorranceXPos = nodeOriginXPos + (nodeXOffset * nodeBranchShift)
	materialCookTorranceYPos = nodeOriginYPos + (nodeYOffset * nodeNumber)

	-- Add the KickAssPBR Material node by calculating the node index # that is being added
	nodeBranchShift = 2
	materialKickAssPBRXPos = nodeOriginXPos + (nodeXOffset * nodeBranchShift)
	materialKickAssPBRYPos = nodeOriginYPos + (nodeYOffset * nodeNumber)

	-- Add the Reflect Material node by calculating the node index # that is being added
	nodeBranchShift = 3
	materialReflectXPos = nodeOriginXPos + (nodeXOffset * nodeBranchShift)
	materialReflectYPos = nodeOriginYPos + (nodeYOffset * nodeNumber)

	-- Add the kas_ShaderBall node by calculating the node index # that is being added
	nodeBranchShift = 4
	shaderBallXPos = nodeOriginXPos + (nodeXOffset * nodeBranchShift)
	shaderBallYPos = nodeOriginYPos + (nodeYOffset * nodeNumber)

	-- Add the BumpMap node by calculating the node index # that is being added
	nodeBranchShift = 1
	bumpmapXPos = nodeOriginXPos + (nodeXOffset * nodeBranchShift)
	bumpmapYPos = nodeOriginYPos + (nodeYOffset * nodeNumber)

	nodeString = ''

	-- Get the channel name mappings
	for i, chan in pairs(imageChannels) do
		if chan == 'BaseColor' then
			baseColorName = GetBasename(imageFilenames[i])
		elseif chan == 'Roughness' then
			roughnessName = GetBasename(imageFilenames[i])
		elseif chan == 'Normal' then
			bumpmapName = 'PBRBumpMap'
			normalName = GetBasename(imageFilenames[i])
		elseif chan == 'Metallic' then
			metallicName = GetBasename(imageFilenames[i])
		elseif chan == 'Height' then
			heightName = GetBasename(imageFilenames[i])
		elseif chan == 'Emissive' then
			emissiveName = GetBasename(imageFilenames[i])
		end
	end

	-- Add a Note node
	if nodeNumber == 1 then
		noteName = 'PBRNote'
		noteText = ''


		-- Note Comments
		noteText = '[Substance Export Type] PBR Metal Rough\\n'
		print('[Substance Export Type] PBR Metal Rough')

		if usePBRMaterial == true then
			noteText = noteText .. '[Material Node] KickAssPBR CustomShader3D\\n'
			print('[Material Node] KickAssPBR CustomShader3D')
		else
			noteText = noteText .. '[Material Node] Cook Torrance/Reflect\\n'
			print('[Material Node] Cook Torrance/Reflect Material')
		end

		noteText = noteText .. '[Images]\\n'

		for i, img in pairs(imageFilenames) do
			noteText = noteText .. ' ' .. ' ' .. GetFilename(img) .. '\\n'
		end

		if useEnvMap == true then
			noteText = noteText .. '[Environment]\\n'
			noteText = noteText .. iblFilename .. '\\n'
			print('[Add Environment Map] ' .. tostring(iblFilename))
		else
			print('[Add Environment Map] ' .. tostring(useEnvMap))
		end

		print('[Add ShaderBall] ' .. tostring(useShaderBall))

		if useNote == true then
			-- Add a note node
			nodeString = nodeString .. AddNoteNode(noteName, noteText, 650, 180, noteNodeXPos, noteNodeYPos)
		end

		print('[Add Note] ' .. tostring(useNote))
	end

	-- Add a material node
	if nodeNumber == 1 then
		-- Add a Cook Torrance / Reflect based non PBR shader
		if usePBRMaterial == false then
			-- Add a Cook Torrance material node
			cookTorranceName = 'PBRCookTorrance'
			-- Material comment field
			cookTorranceText = ''
			nodeString = nodeString .. AddMaterialCookTorranceNode(cookTorranceName, baseColorName, roughnessName, bumpmapName, cookTorranceText, materialCookTorranceXPos, materialCookTorranceYPos)

			-- Add the Simons Town HDR Loader + SphereMap node
			if useEnvMap == true then
				-- Env map enabled

				-- Add a Loader node
				nodeString = nodeString .. AddLoaderNode(iblName, iblFilename, iblFormat, frameExtensionFusionStartFrame, iblLoaderText, loaderIBLXPos, loaderIBLYPos)

				-- Add a SphereMap to the comp
				sphereMapName = 'IBLSphereMap'
				nodeString = nodeString .. AddSphereMapNode(sphereMapName, iblName, spheremapIBLXPos, spheremapIBLYPos)

				-- Add a Reflect material node
				reflectName = 'PBRReflect'
				nodeString = nodeString .. AddMaterialReflectNode(reflectName, bumpmapName, cookTorranceName, sphereMapName, materialReflectXPos, materialReflectYPos)

				if useShaderBall == true then
					-- Add a kas_ShaderBall to the comp
					shaderballName = 'kas_ShaderBall'
					-- nodeString = nodeString .. AddShaderBallNode(shaderballName, cookTorranceName, shaderBallXPos, shaderBallYPos)
					nodeString = nodeString .. AddShaderBallNode(shaderballName, reflectName, shaderBallXPos, shaderBallYPos)
				end
			else
				-- Env map disabled

				if useShaderBall == true then
					-- Add a kas_ShaderBall to the comp
					shaderballName = 'kas_ShaderBall'
					nodeString = nodeString .. AddShaderBallNode(shaderballName, cookTorranceName, shaderBallXPos, shaderBallYPos)
				end
			end
		else
			-- Add a KickAssPBR Material
			-- Add the Simons Town HDR Loader + SphereMap node
			if useEnvMap == true then
				-- Add a Loader node
				nodeString = nodeString .. AddLoaderNode(iblName, iblFilename, iblFormat, frameExtensionFusionStartFrame, iblLoaderText, loaderIBLXPos, loaderIBLYPos)

				-- Add a SphereMap to the comp
				sphereMapName = 'IBLSphereMap'
				nodeString = nodeString .. AddSphereMapNode(sphereMapName, iblName, spheremapIBLXPos, spheremapIBLYPos)
			end

			-- Add a CustomShader3D based KickAssPBR material
			kickassPBRName = 'KickAssPBR'
			kickassPBRText = ''
			kickassShaderTextInputs = [[FuFloat4 BaseColor;\nFuFloat4 Roughness;\nFuFloat4 Metallic;\nFuFloat4 Height;\nFuFloat4 IBL;\nfloat4 Diffuse;\nFuLight Lights[];FuLight Lights[];\nfloat4x4 Projection;\n\n]]
			kickassShaderTextBody = [[float4 Shade(inout FuFragment f) {\n	float4 Kd = BaseColor.Shade(f);\n\n	// f.Normal is in eye space\n	float3 n = f.Normal;\n\n	// Ambient light accumulation buffer\n	float3 aAccum = 0;\n\n	// Diffuse light accumulation buffer\n	float3 dAccum = 0;\n\n	// Per-light isotropic Lambertian lighting\n	float3 Lambert;\n\n	// Surface to Light vector mapped in eye space for each fragment\n	float3 l;\n\n	// Iterate through the Lights[] array and perform shading to fill up the aAccum and dAccum buffers.\n	for(int i = 0; i < Lights.length; i++){\n		// FuLightData holds the AmbientColor, Color, and LightVector\n		FuLightData data = Lights[i].Illuminate(f);\n\n		// Only Ambient lights set the AmbientColor to anything other than zeros.  Also, ambient lights set Color and LightVector to zeros. So each light only will affect either the aAccum or dAccum buffer.\n		aAccum += data.AmbientColor.rgb;\n\n		// Set the LightVector to a unit vector so it becomes purely direction, not distance.\n		l = normalize(data.LightVector);\n\n		// Lambertian lighting is the dot product of the normal and the light directions.  Surfaces pointing toward the light will be bright, those perpendicular to the light will be dark.  Those pointing away will be negative. Saturate() clamps the value to a [0,1] range, so the negative lighting values will be zeroed out.\n		Lambert = saturate(dot(n,l));\n\n		// Ambient lights don't set the Color, but other lights do.  The Color includes shadow maps, decay, projectors, etc..  The light Color gets multiplied by the Lambertian intensity to give the final diffuse color which accumulates in dAccum.\n		dAccum += data.Color.rgb * Lambert;\n	}\n\n	// The final float4 fragment is the Kd, the surface color, multiplied by the summed lighting.  Kd also provides the alpha which is unaffected by lighting.\n	float4 ret = float4(Kd * (dAccum + aAccum) * Diffuse, Kd.a);\n\n	// Return the final shaded output\n	return ret;\n}\n]]
			nodeString = nodeString .. AddMaterialKickAssPBRNode(kickassPBRName, kickassShaderTextInputs, kickassShaderTextBody, baseColorName, roughnessName, bumpmapName, metallicName, heightName, emissiveName, sphereMapName, kickassPBRText, materialKickAssPBRXPos, materialKickAssPBRYPos)

			if useEnvMap == true then
				-- Add a Reflect material node
				reflectName = 'PBRReflect'
				nodeString = nodeString .. AddMaterialReflectNode(reflectName, bumpmapName, kickassPBRName, sphereMapName, materialReflectXPos, materialReflectYPos)
						
				if useShaderBall == true then
					-- Add a kas_ShaderBall to the comp
					shaderballName = 'kas_ShaderBall'
					nodeString = nodeString .. AddShaderBallNode(shaderballName, reflectName, shaderBallXPos, shaderBallYPos)
				end
			else
				-- Env map disabled
								
				if useShaderBall == true then
					-- Add a kas_ShaderBall to the comp
					shaderballName = 'kas_ShaderBall'
					nodeString = nodeString .. AddShaderBallNode(shaderballName, kickassPBRName, shaderBallXPos, shaderBallYPos)
				end
			end
		end
	end

	-- Add a BumpMap node if the current Loader node PBR channel type is 'Normal'
	if nodeChannel == 'Normal' then
		-- BumpMap comment field
		bumpmapText = ''

		-- Add a BumpMap node
		nodeString = nodeString .. AddBumpMapNode(bumpmapName, loaderName, bumpmapText, bumpmapXPos, bumpmapYPos)
	end

	-- Loader node comment field
	loaderText = ''

	-- Add a Loader node
	nodeString = nodeString .. AddLoaderNode(loaderName, loaderFilename, loaderFormat, frameExtensionFusionStartFrame, loaderText, loaderXPos, loaderYPos)

	return nodeString
end

-- Add a note node to the comp
function AddNoteNode(nodeName, nodeText, noteWidth, noteHeight, nodeXPos, nodeYPos)
	textBlock = ''
	textBlock = textBlock .. '\t\t' .. nodeName .. ' = Note {\n'
	textBlock = textBlock .. '\t\t\tInputs = {\n'
	textBlock = textBlock .. '\t\t\t\tComments = Input { Value = "' .. nodeText .. '", }\n'
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t\tViewInfo = StickyNoteInfo {\n'
	textBlock = textBlock .. '\t\t\t\tPos = { ' .. nodeXPos .. ', ' .. nodeYPos .. ' },\n'
	textBlock = textBlock .. '\t\t\t\tFlags = {\n'
	textBlock = textBlock .. '\t\t\t\t\tExpanded = true\n'
	textBlock = textBlock .. '\t\t\t\t},\n'
	textBlock = textBlock .. '\t\t\t\tSize = { ' .. noteWidth .. ', ' .. noteHeight .. ' }\n'
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t},\n'

	return textBlock
end

-- Add a Cook Torrance material to the comp
function AddMaterialCookTorranceNode(nodeName, baseColorNodeName, roughnessNodeName, bumpmapNodeName, nodeText, nodeXPos, nodeYPos)
	textBlock = ''
	textBlock = textBlock .. '\t\t' .. nodeName .. ' = MtlCookTorrance {\n'
	textBlock = textBlock .. '\t\t\tCtrlWZoom = false,\n'
	textBlock = textBlock .. '\t\t\tInputs = {\n'

	-- BaseColor
	-- baseColorNodeName = "PreviewSphere_Sphere_BaseColor"

	if baseColorNodeName then
		textBlock = textBlock .. '\t\t\t\t["Diffuse.Color.Material"] = Input {\n'
		textBlock = textBlock .. '\t\t\t\t\tSourceOp = "' .. baseColorNodeName .. '",\n'
		textBlock = textBlock .. '\t\t\t\t\tSource = "Output",\n'
		textBlock = textBlock .. '\t\t\t\t},\n'
	end

	-- Roughness
	-- roughnessNodeName = "PreviewSphere_Sphere_BaseColor"

	if roughnessNodeName then
		textBlock = textBlock .. '\t\t\t\t["Specular.Roughness.Material"] = Input {\n'
		textBlock = textBlock .. '\t\t\t\t\tSourceOp = "' .. roughnessNodeName .. '",\n'
		textBlock = textBlock .. '\t\t\t\t\tSource = "Output",\n'
		textBlock = textBlock .. '\t\t\t\t},\n'
	end

	textBlock = textBlock .. '\t\t\t\t["Specular.Nest"] = Input { Value = 1, },\n'
	textBlock = textBlock .. '\t\t\t\t["Specular.Roughness"] = Input { Value = 0.2, },\n'

	-- Bumpmap
	-- bumpmapNodeName = "BumpMap1"

	if bumpmapNodeName then
		textBlock = textBlock .. '\t\t\t\t["Bumpmap.Material"] = Input {\n'
		textBlock = textBlock .. '\t\t\t\t\tSourceOp = "' .. bumpmapNodeName .. '",\n'
		textBlock = textBlock .. '\t\t\t\t\tSource = "MaterialOutput",\n'
		textBlock = textBlock .. '\t\t\t\t},\n'
	end

	textBlock = textBlock .. '\t\t\t\tMaterialID = Input { Value = 1, },\n'

	-- Close node
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t\tViewInfo = OperatorInfo {\n'
	textBlock = textBlock .. '\t\t\t\tPos = { ' .. nodeXPos .. ', ' .. nodeYPos .. ' },\n'
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t},\n'

	return textBlock
end

-- Add a KickAssPBR material to the comp
function AddMaterialKickAssPBRNode(nodeName, shaderTextInputs, shaderTextBody, baseColorNodeName, roughnessNodeName, bumpmapNodeName, metallicNodeName, heightNodeName, emissiveNodeName, iblNodeName, nodeText, nodeXPos, nodeYPos)
	textBlock = ''
	textBlock = textBlock .. '\t\t' .. nodeName .. [=[ = Indicated.CustomShaderOperator3D {
			NameSet = true,
