-- Add a SphereMap to the comp
function AddSphereMapNode(nodeName, loaderNodeName, nodeXPos, nodeYPos)
	textBlock = ''
	textBlock = textBlock .. '\t\t' .. nodeName .. ' = SphereMap {\n'
	textBlock = textBlock .. '\t\t\tInputs = {\n'
	textBlock = textBlock .. '\t\t\tRotation = Input { Value = 1, },\n'
	textBlock = textBlock .. '\t\t\tImage = Input {\n'
	textBlock = textBlock .. '\t\t\t\t\tSourceOp = "' .. loaderNodeName .. '",\n'
	textBlock = textBlock .. '\t\t\t\t\tSource = "Output",\n'
	textBlock = textBlock .. '\t\t\t\t},\n'
	textBlock = textBlock .. '\t\t\t\tMaterialIDNest = Input { Value = 1, },\n'
	textBlock = textBlock .. '\t\t\t\tMaterialID = Input { Value = 6, },\n'
	textBlock = textBlock .. '\t\t\t},\n'

	-- Close node
	textBlock = textBlock .. '\t\t\tViewInfo = OperatorInfo {\n'
	textBlock = textBlock .. '\t\t\t\tPos = { ' .. nodeXPos .. ', ' .. nodeYPos .. ' },\n'
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t},\n'

	return textBlock
end

-- Add a BumpMap to the comp
function AddBumpMapNode(bumpmapNodeName, loaderNodeName, nodeText, nodeXPos, nodeYPos)
	textBlock = ''
	textBlock = textBlock .. '\t\t' .. bumpmapNodeName .. ' = BumpMap {\n'
	textBlock = textBlock .. '\t\t\tInputs = {\n'
	textBlock = textBlock .. '\t\t\t\tSourceImageType = Input { Value = 1, },\n'
	textBlock = textBlock .. '\t\t\t\tInput = Input {\n'
	textBlock = textBlock .. '\t\t\t\t\tSourceOp = "' .. loaderNodeName .. '",\n'
	textBlock = textBlock .. '\t\t\t\t\tSource = "Output",\n'
	textBlock = textBlock .. '\t\t\t\t},\n'
	textBlock = textBlock .. '\t\t\t\tMaterialID = Input { Value = 2, },\n'
	textBlock = textBlock .. '\t\t\t},\n'

	-- Close node
	textBlock = textBlock .. '\t\t\tViewInfo = OperatorInfo {\n'
	textBlock = textBlock .. '\t\t\t\tPos = { ' .. nodeXPos .. ', ' .. nodeYPos .. ' },\n'
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t},\n'

	return textBlock
end

-- Add a Reflect material to the comp
function AddMaterialReflectNode(nodeName, bumpmapNodeName, cookTorranceNodeName, sphereMapNodeName, nodeXPos, nodeYPos)
	textBlock = ''
	textBlock = textBlock .. '\t\t' .. nodeName .. ' = MtlReflect {\n'
	textBlock = textBlock .. '\t\t\tCtrlWZoom = false,\n'
	textBlock = textBlock .. '\t\t\tInputs = {\n'

	-- Cook Torrance node connection
	textBlock = textBlock .. '\t\t\t\tBackgroundMaterial = Input {\n'
	textBlock = textBlock .. '\t\t\t\t\tSourceOp = "' .. cookTorranceNodeName .. '",\n'
	textBlock = textBlock .. '\t\t\t\t\tSource = "MaterialOutput",\n'
	textBlock = textBlock .. '\t\t\t\t},\n'

	textBlock = textBlock .. '\t\t\t\t["Reflection.GlancingStrength"] = Input { Value = 0.8, },\n'

	-- HDRI image + SphereMap node connection
	if sphereMapNodeName then
		textBlock = textBlock .. '\t\t\t\t["Reflection.Color.Material"] = Input {\n'
		textBlock = textBlock .. '\t\t\t\t\tSourceOp = "' .. sphereMapNodeName .. '",\n'
		textBlock = textBlock .. '\t\t\t\t\tSource = "MaterialOutput",\n'
		textBlock = textBlock .. '\t\t\t\t},\n'
	end

	textBlock = textBlock .. '\t\t\t\t["Reflection.FaceOnStrength"] = Input { Value = 0.1, },\n'
	textBlock = textBlock .. '\t\t\t\t["Refraction.RefractiveIndex.RGB"] = Input { Value = 1, },\n'
	textBlock = textBlock .. '\t\t\t\t["Refraction.Tint.Red"] = Input { Value = 0, },\n'
	textBlock = textBlock .. '\t\t\t\t["Refraction.Tint.Green"] = Input { Value = 0, },\n'
	textBlock = textBlock .. '\t\t\t\t["Refraction.Tint.Blue"] = Input { Value = 0, },\n'

	-- Bumpmap
	if bumpmapNodeName then
		textBlock = textBlock .. '\t\t\t\t["Bumpmap.Material"] = Input {\n'
		textBlock = textBlock .. '\t\t\t\t\tSourceOp = "' .. bumpmapNodeName .. '",\n'
		textBlock = textBlock .. '\t\t\t\t\tSource = "MaterialOutput",\n'
		textBlock = textBlock .. '\t\t\t\t},\n'
	end

	textBlock = textBlock .. '\t\t\t\tMaterialID = Input { Value = 3, },\n'

	-- Close node
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t\tViewInfo = OperatorInfo {\n'
	textBlock = textBlock .. '\t\t\t\tPos = { ' .. nodeXPos .. ', ' .. nodeYPos .. ' },\n'
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t},\n'

	return textBlock
end

