-- Add a Loader node
function AddLoaderNode(nodeName, filename, format, startFrame, comments, nodeXPos, nodeYPos)

	-- Escape the backwards path slashes on Windows
	if platform == 'Windows' then
		filename = filename:gsub('\\', '\\\\')
	end

	textBlock = ''
	textBlock = textBlock .. '\t\t' .. nodeName .. ' = Loader {\n'
	textBlock = textBlock .. '\t\t\tClips = {\n'
	textBlock = textBlock .. '\t\t\t\tClip {\n'
	textBlock = textBlock .. '\t\t\t\t\tID = "Clip1",\n'
	textBlock = textBlock .. '\t\t\t\t\tFilename = "' .. filename .. '",\n'
	textBlock = textBlock .. '\t\t\t\t\tFormatID = "' .. format .. '",\n'

	-- Load the frame as a still image that has no duration (-1)
	-- textBlock = textBlock .. '\t\t\t\t\tStartFrame = -1,\n'
	-- Does the final frame padding start on frame 1 or frame 0?
	textBlock = textBlock .. '\t\t\t\t\tStartFrame = ' .. startFrame .. ',\n'

	textBlock = textBlock .. '\t\t\t\t\tLengthSetManually = true,\n'
	textBlock = textBlock .. '\t\t\t\t\tTrimIn = 0,\n'
	textBlock = textBlock .. '\t\t\t\t\tTrimOut = 0,\n'
	textBlock = textBlock .. '\t\t\t\t\tExtendFirst = 0,\n'
	textBlock = textBlock .. '\t\t\t\t\tExtendLast = 0,\n'
	textBlock = textBlock .. '\t\t\t\t\tLoop = 0,\n'
	textBlock = textBlock .. '\t\t\t\t\tAspectMode = 0,\n'
	textBlock = textBlock .. '\t\t\t\t\tDepth = 0,\n'
	textBlock = textBlock .. '\t\t\t\t\tTimeCode = 0,\n'
	textBlock = textBlock .. '\t\t\t\t\tGlobalStart = 0,\n'
	textBlock = textBlock .. '\t\t\t\t\tGlobalEnd = 0\n'
	textBlock = textBlock .. '\t\t\t\t},\n'
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t\tCtrlWZoom = false,\n'

	-- Comments text field
	if comments then
		textBlock = textBlock .. '\t\t\tInputs = {\n'
		textBlock = textBlock .. '\t\t\t\tComments = Input { Value = "' .. comments .. '", },\n'
		textBlock = textBlock .. '\t\t\t},\n'
	end

	textBlock = textBlock .. '\t\t\tViewInfo = OperatorInfo {\n'
	textBlock = textBlock .. '\t\t\t\tPos = { ' .. nodeXPos .. ', ' .. nodeYPos .. ' },\n'
	textBlock = textBlock .. '\t\t\t},\n'
	textBlock = textBlock .. '\t\t},\n'

	return textBlock
end

-- Create a UI Manager dialog
function HelpWindow(parentWidth, parentHeight)
	-- Init UI Manager
	local ui = fu.UIManager
	local disp = bmd.UIDispatcher(ui)

	local width,height = 684,740
	local x = fu:GetMousePos()[1]
	local y = fu:GetMousePos()[2]

	-- Help Resources
	local URL = 'https://www.andrewhazelden.com'

	-- Build the new window
	win = disp:AddWindow({
		ID = 'HelpWin',
		TargetID = 'HelpWin',
		WindowTitle = 'Substance PBR Import Help',
		WindowFlags = {
			Window = true,
			WindowStaysOnTopHint = true,
		},
		Geometry = {x + parentWidth - 24, y - parentHeight - 5, width, height},
		Events = {
			Close = true,
			KeyPress = true,
			KeyRelease = true,
		},
		Spacing = 10,

		ui:VGroup{
			ID = 'root',
			-- Add your GUI elements here:

			-- Add the main Message
			ui:TextEdit{
				ID = 'AboutText',
				ReadOnly = true,
				Alignment = {
					AlignHCenter = true,
					AlignTop = true
				},
				Events = {
					AnchorClicked = true,
				},
				HTML = [=[
<h1>About Substance PBR Import</h1>
<h2>]=] .. tostring(_VERSION) .. [=[</h2>

<p>The &quot;Substance PBR Import&quot; script reads the image from the selected Loader node and expands it to import the full set of Substance PBR texture maps.
</p>

<p>The script is compatible with Fusion 9-18.1+ and Resolve 15.1-18.1+.</p>

<h1>Screenshot</h1>

<!-- The Result of Running the Script Screenshot -->
]=] ..ScriptResultImage() .. [=[

<h1>Install</h1>
<p>Copy the &quot;Substance PBR Import.lua&quot; tool script to your Fusion Standalone based "Scripts:/Tool/KickAss ShaderZ/" PathMap folder:</p>

<p><pre>
(Windows) C:\ProgramData\Blackmagic Design\Fusion\Reactor\Deploy\Scripts\Tool\KickAss ShaderZ\
(Linux) /var/BlackmagicDesign/Fusion/Reactor/Deploy/Scripts/Tool/KickAss ShaderZ/
(macOS) /Library/Application Support/Blackmagic Design/Reactor/Deploy/Scripts/Tool/KickAss ShaderZ/
</pre></p>


<h1>Usage</h1>

<p>Step 1. Select a Loader node in the Flow view.</p>

