<p>These maps will be named with a filename formatted like:</p>

<p><pre>image_&lt;map&gt;.ext</pre></p>


<h2>Substance Material Export</h2>

<p>In Substance Painter select the &quot;File &gt;Export Textures...&quot; menu item to prepare your final baked and flattened texture maps.</p>

<!-- File > Export Textures Menu Screenshot -->
]=] .. SubstanceFileExportTexturesMenuImage() .. [=[

<p>In the &quot;Export document...&quot; dialog set the export location using the button at the top of the dialog. Then set the &quot;Config&quot; attribute to use the &quot;PBR MetalRough&quot; option to generate the correct texture maps.</p>

<p>Finally, click the &quot;Export&quot; button to save out the textures.</p>

<!-- Export Document Window Screenshot -->
]=] .. SubstanceExportDocumentMenuImage() .. [=[


]=]
			},
			-- Add clickable links
			ui:VGroup{
				Weight = 0,

				ui:Label{
					ID = 'URL',
					Text = 'Created by Andrew Hazelden: <a style="color: rgb(139,155,216)" href="' .. URL .. '">' .. URL .. '</a>',
					Alignment = {
						AlignHCenter = true,
						AlignTop = true,
					},
					WordWrap = true,
					OpenExternalLinks = true,
				},
			},
		},
	})

	function win.On.HelpWin.Close(ev)
		disp:ExitLoop()
	end

	-- Add your GUI element based event functions here:
	local itm = win:GetItems()

	function win.On.DoneButton.Clicked(ev)
		disp:ExitLoop()
	end

	-- Track if the shift key is currently held down
	shiftKeyPressed = false

	-- The shift key was held down
	function win.On.HelpWin.KeyPress(ev)
		if ev.Key == 0x1000020 then
			shiftKeyPressed = true
		end
	end

	-- The shift key was released
	function win.On.HelpWin.KeyRelease(ev)
		if ev.Key == 0x1000020 then
			shiftKeyPressed = false
		end
	end

	-- Open an HTML link when clicked on in the HTML text area
	function win.On.AboutText.AnchorClicked(ev)
		if shiftKeyPressed == true then
			-- The shift key was pressed
			print('[URL Preview] ', ev.URL)
		else
			-- Open the URL
			bmd.openurl(ev.URL)
		end
	end

	-- The app:AddConfig() command that will capture the "Control + W" or "Control + F4" hotkeys so they will close the window instead of closing the foreground composite.
	app:AddConfig('HelpWin', {
		Target {
			ID = 'HelpWin',
		},

		Hotkeys {
			Target = 'HelpWin',
			Defaults = true,
			
			CONTROL_W = 'Execute{cmd = [[app.UIManager:QueueEvent(obj, "Close", {})]]}',
			CONTROL_F4 = 'Execute{cmd = [[app.UIManager:QueueEvent(obj, "Close", {})]]}',
			ESCAPE = 'Execute{cmd = [[app.UIManager:QueueEvent(obj, "Close", {})]]}',
		},
	})

	win:Show()
	disp:RunLoop()
	win:Hide()

	return win,win:GetItems()
end

