-- Show a settings dialog
function GetSettings(toolName)
	-- GetSettings function exit state flag
	continueScript = true

	-- Should a CustomShader3D node be used, or will a fallback Cook Torrance/Reflect material be added?
	local usePBRMaterialDefault = GetPreferenceData('Substance.PBRImport.usePBRMaterial', false, printStatus)

	-- Should an environment map be added?
	local useEnvMapDefault = GetPreferenceData('Substance.PBRImport.useEnvMap', true, printStatus)

	-- Should a kas_ShaderBall node be added?
	local useShaderBallDefault = GetPreferenceData('Substance.PBRImport.useShaderBall', true, printStatus)

	-- Should a note node be added?
	local useNoteDefault = GetPreferenceData('Substance.PBRImport.useNote', false, printStatus)

	-- Display the "About Blobbylize" dialog
	ui = app.UIManager
	disp = bmd.UIDispatcher(ui)

	-- Configure the window Size
	local originX, originY, width, height = 100, 110, 360, 185

	-- Create the new UI Manager Window
	local win = disp:AddWindow({
		ID = 'SubstancePBRImport',
		TargetID = 'SubstancePBRImport',
		WindowTitle = 'Substance PBR Import | ' .. tostring(toolName or ''),
		WindowFlags = {
			Window = true,
			-- WindowStaysOnTopHint = true,
		},
		Geometry = {
			originX,
			originY,
			width,
			height,
		},
		ui:VGroup{
			ID = 'root',
			-- Add your GUI elements here:
			ui:HGroup{
				Weight = 0.1,
				ui:Label{
					ID = 'PBRMaterialLabel',
					Text = 'PBR Surface Material',
				},
				ui:ComboBox{
					ID = 'PBRMaterialCombo',
					Text = 'PBR Surface Material',
				},
			},
			ui:CheckBox{
				ID = 'AddEnviromentMapCheckbox',
				Text = 'Add Environment Map',
				Checked = useEnvMapDefault,
			},
			ui:CheckBox{
				ID = 'AddShaderBallCheckbox',
				Text = 'Add Shader Ball',
				Checked = useShaderBallDefault,
			},
			ui:CheckBox{
				ID = 'AddNoteCheckbox',
				Text = 'Add Note',
				Checked = useNoteDefault,
			},
			ui:CheckBox{
				ID = 'ResetToDefaultsCheckbox',
				Text = 'Reset to Defaults',
				Checked = false,
			},
			ui:HGroup{
				Weight = 0.1,
				ui:Button{
					Weight = 0.001,
					ID = 'HelpButton',
					Text = '?',
					MinimumSize = {24, 24},
				},
				ui:Button{
					Weight = 1.0,
					ID = 'CreatePBRMaterialButton',
					Text = 'Create PBR Material',
				},
			},
		},
	})

	-- Add your GUI element based event functions here:
	itm = win:GetItems()

	-- Add the items to the ComboBox menu
	itm.PBRMaterialCombo:AddItem('Cook Torrance/Reflect')
	itm.PBRMaterialCombo:AddItem('CustomShader3D (Alpha)')

	-- Select the default ComboBox menu item
	if usePBRMaterialDefault == false then
		-- Cook Torrance/Reflect
		itm.PBRMaterialCombo.CurrentIndex = 0
	else
		-- CustomShader3D
		itm.PBRMaterialCombo.CurrentIndex = 1
	end

	-- The window was closed
	function win.On.SubstancePBRImport.Close(ev)
		-- Skip importing the material
		continueScript = false

		print('[Window Closed] Exiting Script')
		disp:ExitLoop()
	end

	-- Help (?) button was clicked
	function win.On.HelpButton.Clicked(ev)
		print('[Show Help]')

		-- Display a UI Manager based help window
		HelpWindow(width, height)
	end

	-- Reset the script prefs to their factor defaults
	function win.On.ResetToDefaultsCheckbox.Clicked(ev)
		if itm.ResetToDefaultsCheckbox.Checked == true then
			-- Cook Torrance/Reflect
			itm.PBRMaterialCombo.CurrentIndex = 0

			itm.AddEnviromentMapCheckbox.Checked = true
			itm.AddShaderBallCheckbox.Checked = true
			itm.AddNoteCheckbox.Checked = false
			itm.ResetToDefaultsCheckbox.Checked = false

			print('[Reset to Defaults] Clearing Preferences')
			SetPreferenceData('Substance.PBRImport.usePBRMaterial', nil, printStatus)
			SetPreferenceData('Substance.PBRImport.useEnvMap', nil, printStatus)
			SetPreferenceData('Substance.PBRImport.useShaderBall', nil, printStatus)
			SetPreferenceData('Substance.PBRImport.useNote', nil, printStatus)

		end
	end

	-- Import the PBR materials
	function win.On.CreatePBRMaterialButton.Clicked(ev)
		if itm.PBRMaterialCombo.CurrentIndex == 0 then
			-- Cook Torrance/Reflect
			SetPreferenceData('Substance.PBRImport.usePBRMaterial', false, printStatus)
		else
			-- CustomShader3D
			SetPreferenceData('Substance.PBRImport.usePBRMaterial', true, printStatus)
		end

		SetPreferenceData('Substance.PBRImport.useEnvMap', itm.AddEnviromentMapCheckbox.Checked, printStatus)
		SetPreferenceData('Substance.PBRImport.useShaderBall', itm.AddShaderBallCheckbox.Checked, printStatus)
		SetPreferenceData('Substance.PBRImport.useNote', itm.AddNoteCheckbox.Checked, printStatus)

		disp:ExitLoop()
	end

	-- The app:AddConfig() command that will capture the "Control + W" or "Control + F4" hotkeys so they will close the window instead of closing the foreground composite.
	app:AddConfig('SubstancePBRImport', {
		Target {
			ID = 'SubstancePBRImport',
		},

		Hotkeys {
			Target = 'SubstancePBRImport',
			Defaults = true,

			CONTROL_W  = 'Execute{cmd = [[app.UIManager:QueueEvent(obj, "Close", {})]]}',
			CONTROL_F4 = 'Execute{cmd = [[app.UIManager:QueueEvent(obj, "Close", {})]]}',
			ESCAPE = 'Execute{cmd = [[app.UIManager:QueueEvent(obj, "Close", {})]]}',
		},
	})

	-- Init the window
	win:Show()
	disp:RunLoop()
	win:Hide()

	app:RemoveConfig('SubstancePBRImport')
	collectgarbage()

	-- Should a CustomShader3D node be used, or will a fallback Cook Torrance/Reflect material be added?
	local usePBRMaterial = GetPreferenceData('Substance.PBRImport.usePBRMaterial', false, printStatus)

	-- Should an environment map be added?
	local useEnvMap = GetPreferenceData('Substance.PBRImport.useEnvMap', true, printStatus)

	-- Should a kas_ShaderBall node be added?
	local useShaderBall = GetPreferenceData('Substance.PBRImport.useShaderBall', true, printStatus)

	-- Should a note node be added?
	local useNote = GetPreferenceData('Substance.PBRImport.useNote', false, printStatus)

	print('[PBR Material] ' .. tostring(usePBRMaterial))
	print('[Env Map] ' .. tostring(useEnvMap))
	print('[Shader Ball] ' .. tostring(useShaderBall))
	print('[Note] ' .. tostring(useNote))

	return usePBRMaterial, useEnvMap, useShaderBall, useNote, continueScript
end

-- Where the magic happens
function Main()
	print('[Substance PBR Import] By Andrew Hazelden <andrew@andrewhazelden.com>')

	-- List the selected Node in Fusion
	local selectedNode = tool or comp.ActiveTool
	if selectedNode and selectedNode:GetAttrs() and selectedNode:GetAttrs().TOOLS_RegID == 'Loader' then
		print('[Selected Node] ', selectedNode.Name)
		toolAttrs = selectedNode:GetAttrs()

		-- Show a settings dialog
		local usePBRMaterial, useEnvMap, useShaderBall, useNote, continueScript = GetSettings(selectedNode.Name)

		-- Make sure the cancel button wasn't pressed
		if continueScript == true then
			-- Read data from either a the loader and saver nodes
			if toolAttrs.TOOLS_RegID == 'Loader' then
				-- filename = comp:MapPath(selectedNode.Clip[fu.TIME_UNDEFINED])
				filename = NormalizeSlashes(selectedNode.Clip[fu.TIME_UNDEFINED])
				if filename then
					-- print('[Filename] ' .. tostring(filename))

					-- Split the filename apart
					parentDirectory, currentDirectory, currentFile, currentFileNoExt, currentExtension = SplitFilepath(filename)

					-- Extract the Substance PBR channel type from the filename
					basename = string.gsub(currentFileNoExt or '', '[_]%w+$', '_')
					-- print('[Basename] ' .. tostring(currentFileNoExt))
					-- print('[Basename] ' .. tostring(basename))

					parentChannel = ''
					for i, chan in pairs(channels) do
						if string.match(currentFileNoExt, chan) then
							parentChannel = chan
						end
					end
					print('[Parent Channel] ' .. tostring(parentChannel))
					print('\n')

					-- print('[Scanning] PBR Metal Roughness Maps')
					for i, chan in pairs(channels) do
						-- Build the filename
						local file = tostring(parentDirectory or 'Comp:/') .. tostring(currentDirectory or '') .. tostring(basename) .. tostring(chan) .. tostring(currentExtension)
						-- print('[Chan File] ' .. tostring(file))

						-- Expand the PathMap temporarily and check if the file exists on disk
						if bmd.fileexists(comp:MapPath(file)) then
							-- Add the new file to the Lua table of the image filenames
							imageFilenames[i] = file
							imageChannels[i] = chan

							-- print('[Found] ' .. tostring(imageFilenames[i]) .. '\t[Chan] ' .. tostring(imageChannels[i]))
						end
					end
					-- print('\n')
				end
			else
				print('[Selection Error] No PBR metal roughness texture map based Loader node was selected. Please select a Loader node in the flow view before running this script again.')
				return
			end


			-- List the PBR texture map images that exist
			print('[Debug]')
			dump(imageFilenames)
			dump(imageChannels)
			print('\n')

			-- Add an undo item
			comp:StartUndo("PBR Import")

			-- Lock the comp flow area
			comp:Lock()

			-- Create the new image nodes for the comp
			AddImageNodes(usePBRMaterial, useEnvMap, useShaderBall, useNote)

			-- Unlock the comp flow area
			comp:Unlock()

			-- Close the undo item
			comp:EndUndo(true)
		end

		print('[Done]')
	elseif SelectAFile and SelectAFile == true then
		-- A file was provided via a .fu menu entry dialog hook

		selectedPath = tostring(fu:RequestFile('Comp:/') or '')
		print('[File] ', selectedPath)

		-- Exit if the file path is nil
		if not selectedPath or selectedPath == '' then
			print('[Selection Error] No PBR metal roughness texture map was selected. Please select a texture in the file dialog when you run the Import PBR Textures menu item again.')
			return
		end

		-- Show a settings dialog
		local usePBRMaterial, useEnvMap, useShaderBall, useNote, continueScript = GetSettings(GetBasename(selectedPath or '') or '')

		-- Make sure the cancel button wasn't pressed
		if continueScript == true then
			filename = NormalizeSlashes(selectedPath)
			if filename then
				-- print('[Filename] ' .. tostring(filename))

				-- Split the filename apart
				parentDirectory, currentDirectory, currentFile, currentFileNoExt, currentExtension = SplitFilepath(filename)

				-- Extract the Substance PBR channel type from the filename
				basename = string.gsub(currentFileNoExt or '', '[_]%w+$', '_')
				-- print('[Basename] ' .. tostring(currentFileNoExt))
				-- print('[Basename] ' .. tostring(basename))

				parentChannel = ''
				for i, chan in pairs(channels) do
					if string.match(currentFileNoExt, chan) then
						parentChannel = chan
					end
				end
				print('[Parent Channel] ' .. tostring(parentChannel))
				print('\n')

				-- print('[Scanning] PBR Metal Roughness Maps')
				for i, chan in pairs(channels) do
					-- Build the filename
					local file = tostring(parentDirectory or 'Comp:/') .. tostring(currentDirectory or '') .. tostring(basename) .. tostring(chan) .. tostring(currentExtension)
					-- print('[Chan File] ' .. tostring(file))

					-- Expand the PathMap temporarily and check if the file exists on disk
					if bmd.fileexists(comp:MapPath(file)) then
						-- Add the new file to the Lua table of the image filenames
						imageFilenames[i] = file
						imageChannels[i] = chan

						-- print('[Found] ' .. tostring(imageFilenames[i]) .. '\t[Chan] ' .. tostring(imageChannels[i]))
					end
				end
				-- print('\n')
			end


			-- List the PBR texture map images that exist
			print('[Debug]')
			dump(imageFilenames)
			dump(imageChannels)
			print('\n')

			-- Add an undo item
			comp:StartUndo("PBR Import")

			-- Lock the comp flow area
			comp:Lock()

			-- Create the new image nodes for the comp
			AddImageNodes(usePBRMaterial, useEnvMap, useShaderBall, useNote)

			-- Unlock the comp flow area
			comp:Unlock()

			-- Close the undo item
			comp:EndUndo(true)
		end

		print('[Done]')
	else
		print('[Selection Error] No PBR metal roughness texture map based Loader node was selected. Please select a Loader node in the flow view before running this script again.')
		return
	end
end

-- Start the script
jit.off()
Main()

